const text = $input.first().json.output || "";

const maxLength = 3500;
const chunks = [];

for (let i = 0; i < text.length; i += maxLength) {
  chunks.push(text.slice(i, i + maxLength));
}

return chunks.map((chunk, index) => ({
  json: {
    text: chunk,
    part: index + 1,
    total: chunks.length
  }
}));
